const profileNameplateAssets = Object.keys(import.meta.glob('/nameplates/*.webm')).map(path=>path.split('/').pop()!).sort((a,b)=>a.localeCompare(b))
const profileFrameAssets = Object.keys(import.meta.glob('/avatar-frames/*.png')).map(path=>path.split('/').pop()!).sort((a,b)=>a.localeCompare(b))
const attachmentDB=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open('memento-attachments',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})
// Convert imported paths/names into a predictable ASCII IndexedDB key. Some export folder names contain characters that IndexedDB rejects as keys.
const attachmentKey=(id:string)=>'memento-'+Array.from(String(id??'')).map(ch=>ch.codePointAt(0)!.toString(16)).join('_')
const storeAttachment=async(id:string,file:File)=>{const db=await attachmentDB();const key=attachmentKey(id);await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');const store=tx.objectStore('files');if(store.keyPath!==null){const value:any={blob:file};if(typeof store.keyPath==='string')value[store.keyPath]=key;else throw new Error('Unsupported attachment database key path.');store.put(value)}else store.put(file,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Attachment storage was aborted.'))});db.close()}
const readAttachment=async(id:string)=>{const db=await attachmentDB();return new Promise<Blob|null>((resolve,reject)=>{const store=db.transaction('files').objectStore('files'),req=store.get(attachmentKey(id));req.onsuccess=()=>{const value=req.result;if(value){resolve(value?.blob||value);db.close();return}const legacy=store.get(id);legacy.onsuccess=()=>{const old=legacy.result;resolve(old?.blob||old||null);db.close()};legacy.onerror=()=>{reject(legacy.error);db.close()}};req.onerror=()=>{reject(req.error);db.close()}})}
const deleteAttachment=async(id:string)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite'),store=tx.objectStore('files');store.delete(attachmentKey(id));store.delete(id);tx.oncomplete=()=>{resolve();db.close()};tx.onerror=()=>{reject(tx.error);db.close()}})}
