type ChatImportRecord={id:string;platform:'instagram'|'whatsapp';importedAt:number;count:number}
type FollowData={batch:string;importedAt:number;following:{username:string;href:string;timestamp:number}[];followers:{username:string;href:string;timestamp:number}[]}
const chatDataDB=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open('memento-chat-data',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('chats'))req.result.createObjectStore('chats')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})
const loadChatData=async()=>{const db=await chatDataDB();return new Promise<ImportedConversation[]>((resolve,reject)=>{const req=db.transaction('chats').objectStore('chats').get('all');req.onsuccess=()=>{resolve(Array.isArray(req.result)?req.result:[]);db.close()};req.onerror=()=>{reject(req.error);db.close()}})}
const saveChatData=async(chats:ImportedConversation[])=>{const db=await chatDataDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('chats','readwrite');tx.objectStore('chats').put(chats,'all');tx.oncomplete=()=>{resolve();db.close()};tx.onerror=()=>{reject(tx.error);db.close()};tx.onabort=()=>{reject(tx.error||new Error('Chat storage aborted'));db.close()}})}
const stripDirection=(v:string)=>v.replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,'').trim()
const decodeEntities=(v:string)=>v.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi,(whole,code:string)=>{if(code[0]==='#'){const n=code[1]?.toLowerCase()==='x'?parseInt(code.slice(2),16):parseInt(code.slice(1),10);return Number.isFinite(n)&&n>=0&&n<=0x10ffff?String.fromCodePoint(n):whole}return ({amp:'&',lt:'<',gt:'>',quot:'"',apos:"'"} as Record<string,string>)[code.toLowerCase()]||whole})
