const cleanInstagramText=(value:string)=>repairInstagramMojibake(decodeEntities(value.replace(/\\u([0-9a-f]{4})/gi,(_,hex)=>String.fromCharCode(parseInt(hex,16))).replace(/\\n/g,'\n').replace(/\\r/g,'\r'))).normalize('NFC')
